package cn.safetyledger.app.security;
import android.security.keystore.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.Base64;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;
public final class SecretStore{private static final String ALIAS="safety-ledger-local-secrets-v1";private SecretKey key()throws Exception{KeyStore k=KeyStore.getInstance("AndroidKeyStore");k.load(null);if(!k.containsAlias(ALIAS)){KeyGenerator g=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder(ALIAS,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).setKeySize(256).build());g.generateKey();}return((KeyStore.SecretKeyEntry)k.getEntry(ALIAS,null)).getSecretKey();}public String encrypt(String s)throws Exception{if(s==null||s.isBlank())return"";Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key());byte[]v=c.doFinal(s.getBytes(StandardCharsets.UTF_8)),iv=c.getIV(),all=new byte[iv.length+v.length];System.arraycopy(iv,0,all,0,iv.length);System.arraycopy(v,0,all,iv.length,v.length);return Base64.getEncoder().encodeToString(all);}public String decrypt(String s)throws Exception{if(s==null||s.isBlank())return"";byte[]a=Base64.getDecoder().decode(s),iv=java.util.Arrays.copyOfRange(a,0,12),v=java.util.Arrays.copyOfRange(a,12,a.length);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,iv));return new String(c.doFinal(v),StandardCharsets.UTF_8);}}
